        table.insert(arr,pwd)
    else
        arr["phone"] = phone
        arr["password"] = pwd
    end
    require(NetworkLoadingView_filePath):showLoading("正在登入")
    cct.getDateForApp("loginWithPhone", arr, "V")

end
